# chain over j (ssq, ymax): fused into 2 states (ssq, ymax.h0); derived: ymax.h0
#   ymax.h0 = max_j x[i, j]    (left when the contexts of ymax are taken out of its reduction)
# Merge operands must represent non-empty parts; execution skips empty partitions.
def merge_j(a, b):
    return (
        (a[0] + b[0]),  # ssq
        tir.max(a[1], b[1]),  # ymax_h0
    )

j = te.reduce_axis((1, m), name="j")

def compute_j(i):
    # TE's initialization hook holds the first leaf, not an empty state.
    def identity_j(t0, t1):
        return (
            (x[i, 0] * x[i, 0]),  # ssq
            x[i, 0],  # ymax_h0
        )
    fused_j = te.comm_reducer(merge_j, identity_j, name="fused_j")
    return fused_j(
        (
            (x[i, j] * x[i, j]),  # ssq
            x[i, j],  # ymax_h0
        ),
        axis=j,
    )

ssq, ymax_h0 = te.compute(
    (n,), compute_j,
